/*background image overlay*/
.article-cards-overlay {
	position: relative; 
	width: 100%;
	display: flex;
	align-items: center;
	justify-content: center;
	background-size: cover;
    overflow: hidden;
	z-index: 100;
}
.article-cards-overlay::before {
    content: "";
    position: absolute;
    top: 0px;
    right: 0px;
    bottom: 0px;
    left: 0px;
    background-color: rgba(0,0,0,0.5);
}

/* position author on top of cards */
.article-cards-author {
  position: absolute;
  top: 0px;
  margin-bottom: 7px;
}


